@js:
var b = 'https://www.szndz.com';
var kw = String(key);
var sp = b + '/user/search.html?q=' + java.encodeURI(kw);
var h = '' + java.ajax(sp);
var names = ['vw','abw','ru','jrt','van','fw','cwl','gpr','uyoo','tz','euu','tsn','eju','um','fp','dvm','jpk','deblkx','ht','azy','sna','wqx','fpp','rup','jwj','bgt','qp','yf','cw','wq','sign'];
var parts = ['q=' + java.encodeURI(kw)];
for (var i = 0; i < names.length; i++) {
 var n = names[i];
 var mk = 'var ' + n;
 var v = '';
 var from = 0;
 var i1 = -1;
 while (true) {
 var i0 = h.indexOf(mk, from);
 if (i0 < 0) break;
 var pe = i0 + mk.length;
 while (pe < h.length && (h.charAt(pe) == ' ' || h.charAt(pe) == '\t')) pe++;
 if (h.charAt(pe) == '=') { i1 = pe; break; }
 from = i0 + 1;
 }
 if (i1 >= 0) {
 var q1 = h.indexOf('"', i1);
 var q2 = h.indexOf('"', q1 + 1);
 v = h.substring(q1 + 1, q2);
 }
 if (n == 'bgt' && v.length > 0) v = v.substring(0, v.length - 1);
 parts.push(n + '=' + java.encodeURI(v));
}
b + '/api/search,{"method":"POST","body":"' + parts.join('&') + '"}'

